using System;using System.Linq;using System.Reflection;using System.Collections.Generic;using Unity.Collections;using Unity.Entities;using Unity.Mathematics;using Unity.Rendering;using Unity.Transforms;using UnityEngine;using UnityEditor;using Newtonsoft.Json.Linq;using Game.Components;using Game.Rendering;using Game.Rendering.Contracts;
namespace Game.Editor { public static partial class SkirmishGroundSourceFitSurvey {
 static JArray S050Matrix(Matrix4x4 value){var result=new JArray();for(int row=0;row<4;row++)for(int column=0;column<4;column++){float v=value[row,column];Require(!float.IsNaN(v)&&!float.IsInfinity(v),"Finite original water matrix required");result.Add(new JObject{["value"]=v,["bits"]=BitConverter.ToUInt32(BitConverter.GetBytes(v),0).ToString("x8")});}return result;}
 static JObject S050FixedMapBounds(Bounds value){Require(new[]{value.center.x,value.center.y,value.center.z,value.extents.x,value.extents.y,value.extents.z}.All(v=>!float.IsNaN(v)&&!float.IsInfinity(v))&&value.extents.x>=0&&value.extents.y>=0&&value.extents.z>=0,"Finite nonnegative original bounds required");return new JObject{["center"]=S050Vector(value.center),["extents"]=S050Vector(value.extents)};}
 static object S050OriginalSnapshotHelper(string name,params object[] args){var method=typeof(SkirmishBakedActorSnapshotExporter).GetMethod(name,BindingFlags.Static|BindingFlags.NonPublic);Require(method!=null,"Original finite native exporter helper missing: "+name);try{return method.Invoke(null,args);}catch(TargetInvocationException e){throw e.InnerException??e;}}
 static void S050CaptureFixedMapReadDomain(EntityManager em,GridConfig grid,JObject report,Dictionary<string,string> pins,Dictionary<UnityEngine.Object,S050AssetIdentity> observed,JObject locators)=> CapturePinnedFixedMapReadDomain(em,grid,report,pins,observed,locators,S050CitySha,"opmap.ch05.citywide_alert","OriginalCitywideFixedMapReadDomain");
 static void CapturePinnedFixedMapReadDomain(EntityManager em,GridConfig grid,JObject report,Dictionary<string,string> pins,Dictionary<UnityEngine.Object,S050AssetIdentity> observed,JObject locators,string sourceSha,string mapId,string kind){
  var output=new JObject{["schemaVersion"]=1,["kind"]=kind,["sourceDefinitionSha256"]=sourceSha,["operationMapId"]=mapId,["worldSequence"]=em.WorldUnmanaged.SequenceNumber,["worldName"]=em.World.Name,["readerScope"]="Original RenderBoundsPresentation.Create with explicit same streaming EntityManager; no ambient gateway reads or rebinding",["stage"]="context",["actorOrMissionStateExported"]=false,["sourceFitCertified"]=false,["liveOccupancyMeasured"]=false,["actualMaterializedYProved"]=false,["missionReady"]=false};report["fixedMapReadDomain"]=output;
  var before=em.EntityOrderVersion;using var matches=em.CreateEntityQuery(typeof(SkirmishMatchState));Require(matches.CalculateEntityCount()==0,"Original streaming fixture must remain without a match");output["matchQueryCount"]=matches.CalculateEntityCount();output["gridFrame"]=new JObject{["width"]=grid.Width,["height"]=grid.Height,["origin"]=S050Vector(new Vector3(grid.Origin.x,grid.Origin.y,grid.Origin.z)),["cellSize"]=grid.CellSize};var ambient=RenderBoundsGateway.Provider;output["ambientGatewayPresent"]=ambient!=null;output["ambientGatewayType"]=ambient==null?null:ambient.GetType().AssemblyQualifiedName;output["ambientGatewayUsed"]=false;var reader=RenderBoundsPresentation.Create();output["directReaderType"]=reader.GetType().AssemblyQualifiedName;
  output["stage"]="mesh-read-dependencies";using(var query=em.CreateEntityQuery(typeof(RenderMeshArray),typeof(MaterialMeshInfo),typeof(LocalToWorld))){output["renderMeshQueryCount"]=query.CalculateEntityCount();using var entities=query.ToEntityArray(Allocator.Temp);Require(entities.Length<=100000,"Finite fixed-map mesh domain required");var seen=new HashSet<string>(StringComparer.Ordinal);foreach(var entity in entities){var mesh=em.GetSharedComponentManaged<RenderMeshArray>(entity).GetMesh(em.GetComponentData<MaterialMeshInfo>(entity));if(mesh==null)continue;string path=AssetDatabase.GetAssetPath(mesh);Require(!string.IsNullOrEmpty(path),"Original map mesh asset identity required");if(seen.Add(path))S050CleanConsumedAsset(path,pins,observed,locators);}} 
  output["stage"]="original-water";var water=new NativeList<RenderSurfaceFootprint>(Allocator.Temp);try{reader.CollectWaterFootprints(em,ref water);Require(water.Length<=100000,"Finite water domain required");var rows=new JArray();foreach(var value in water)rows.Add(new JObject{["worldToLocalRowMajor"]=S050Matrix(value.WorldToLocal),["localBounds"]=S050FixedMapBounds(value.LocalBounds),["worldBounds"]=S050FixedMapBounds(value.WorldBounds)});output["waterFootprints"]=rows;output["waterFootprintCount"]=rows.Count;output["waterAuthority"]="Original RenderBoundsPresentation.Reader.CollectWaterFootprints";output["physicalWaterGeometryCaptured"]=true;output["activeMissionCreateMaskExecuted"]=false;}finally{water.Dispose();}
  output["stage"]="original-authored-bounds";int count=reader.CountAuthoredBuildingGeometry(em);var bounds=new NativeList<Bounds>(Allocator.Temp);try{reader.CollectAuthoredBuildingBounds(em,ref bounds);Require(count==bounds.Length&&count<=100000,"Original authored count/collect parity required");output["authoredBuildingCount"]=count;var authoredRows=new JArray();foreach(var bound in bounds)authoredRows.Add(S050FixedMapBounds(bound));output["authoredBuildingBounds"]=authoredRows;}finally{bounds.Dispose();}
  output["stage"]="original-navigation-blockers";var missing=new JArray();output["authoredNavigationBlockers"]=(JArray)S050OriginalSnapshotHelper("CaptureAuthoredNavigationBlockers",em,missing);output["unsupportedSelectedNavigationValues"]=missing;Require(missing.Count==0,"Original selected navigation scalar domain unsupported");
  output["stage"]="original-drop-bounds";output["dropClearanceBounds"]=(JObject)S050OriginalSnapshotHelper("CaptureSourceDropClearanceBounds",em,reader);output["ownedProjectionWrites"]="Original exporter applies package AABB.Transform to WorldRenderBounds in this disposable streaming world; not a zero-write claim";output["structuralVersionBefore"]=before;output["structuralVersionAfter"]=em.EntityOrderVersion;Require(before==em.EntityOrderVersion,"Fixed-map collection changed structural version");output["gatewayReferenceUnchanged"]=ReferenceEquals(ambient,RenderBoundsGateway.Provider);Require(ReferenceEquals(ambient,RenderBoundsGateway.Provider),"Global gateway changed during fixed-map read");output["stage"]="Collected";
 }
